// RxAliasMap names one of the AliasMaps.
enum RxAliasMap {
	category
	binary_property
	general_category
	script
}

// rx_alias_to_short ports AliasMap#toShort.
fn rx_alias_to_short(m RxAliasMap, key string) string {
	return match m {
		.category { rx_category_alias_to_short[key] or { key } }
		.binary_property { rx_binary_property_alias_to_short[key] or { key } }
		.general_category { rx_general_category_alias_to_short[key] or { key } }
		.script { rx_script_alias_to_short[key] or { key } }
	}
}

// rx_alias_to_long ports AliasMap#toLong.
fn rx_alias_to_long(m RxAliasMap, key string) string {
	return match m {
		.category { rx_category_alias_to_long[key] or { key } }
		.binary_property { rx_binary_property_alias_to_long[key] or { key } }
		.general_category { rx_general_category_alias_to_long[key] or { key } }
		.script { rx_script_alias_to_long[key] or { key } }
	}
}
